extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi senza errori"):
		return

	check("has_alarm", has_function(main, "suona_allarme"), "main.gd deve contenere suona_allarme(livello)")
	check("has_closest", has_function(main, "trova_nemico_piu_vicino"), "main.gd deve contenere trova_nemico_piu_vicino(punto)")

	call_if_exists(main, "suona_allarme", [2])
	await wait_frames(2)

	var enemies := get_tree().get_nodes_in_group("nemici")
	var all_alerted := true
	for enemy in enemies:
		var alert = get_prop(enemy, "alert_level")
		if alert != 2:
			all_alerted = false
			break
	check("alarm_called", all_alerted, "suona_allarme(2) deve impostare alert_level a 2 su tutti i nodi del gruppo nemici")

	var closest_enemy = call_if_exists(main, "trova_nemico_piu_vicino", [Vector2(110, 100)])
	var enemy_1 := find_by_name(main, "Enemy1")
	check("finds_correct_closest", closest_enemy == enemy_1, "Il nemico più vicino al punto (110, 100) deve essere Enemy1")

