extends Sprite2D

var alert_level: int = 0


func _ready() -> void:
	add_to_group("nemici")


func allerta(livello: int) -> void:
	alert_level = livello
	if alert_level == 1:
		modulate = Color.YELLOW
	elif alert_level >= 2:
		modulate = Color.RED
	else:
		modulate = Color.WHITE

