extends Node2D

# Sistema di sorveglianza centrale


func _ready() -> void:
	print("Centrale di sicurezza attiva.")


func suona_allarme(livello: int) -> void:
	get_tree().call_group("nemici", "allerta", livello)


func trova_nemico_piu_vicino(punto: Vector2) -> Node2D:
	var nemici: Array[Node] = get_tree().get_nodes_in_group("nemici")
	var piu_vicino: Node2D = null
	var distanza_minima: float = 999999.0

	for nodo in nemici:
		var nemico := nodo as Node2D
		if nemico == null:
			continue
		var dist: float = nemico.position.distance_to(punto)
		if dist < distanza_minima:
			distanza_minima = dist
			piu_vicino = nemico

	return piu_vicino
